const rows = $input.all().map(i => i.json).filter(r => r && r.task_id);
const agents = {};
const needs_owner = [];
for (const r of rows) {
  const id = String(r.assigned_to_agent || '').trim();
  if (id) {
    const a = agents[id] || (agents[id] = { open: 0, in_progress: 0, queued: 0, last_update: null, latest_objective: '' });
    a.open += 1;
    if (r.status === 'in_progress') a.in_progress += 1; else a.queued += 1;
    const u = r.updated_at || r.created_at || null;
    if (u && (!a.last_update || String(u) > String(a.last_update))) { a.last_update = u; a.latest_objective = String(r.objective || '').slice(0, 120); }
  }
  if (r.human_action_required === true || String(r.blocked_by || '').toLowerCase() === 'baher' || id === 'baher_owner') {
    needs_owner.push({ task_id: r.task_id, objective: String(r.objective || '').slice(0, 160), next_action: String(r.next_action || '').slice(0, 220), priority: r.priority || '', created_by: r.created_by_agent || '', assigned_to: id, due_at: r.due_at || null, updated_at: r.updated_at || null });
  }
}
return [{ json: { agents, needs_owner, task_rows: rows.length } }];

const agg = $('Aggregate Tasks').first().json || { agents: {}, needs_owner: [], task_rows: 0 };
const agents = agg.agents || {};
const reg = $input.all().map(i => i.json).filter(r => r && r.agent_id);
for (const r of reg) {
  const id = String(r.agent_id).trim();
  const a = agents[id] || (agents[id] = { open: 0, in_progress: 0, queued: 0, last_update: null, latest_objective: '' });
  a.enabled = r.enabled;
  a.status = r.status || null;
  a.autonomy_level = r.autonomy_level || null;
  a.health_status = r.health_status || null;
  a.reports_to = r.reports_to || null;
  a.agent_name = r.agent_name || null;
  a.registry_updated_at = r.updated_at || null;
  for (const k of Object.keys(r)) { if (/heartbeat/i.test(k)) a[k] = r[k]; }
}
let inProg = 0, open = 0, active = 0, paused = 0;
for (const k of Object.keys(agents)) { const a = agents[k]; inProg += a.in_progress || 0; open += a.open || 0; if (a.status === 'paused' || a.enabled === false) paused += 1; else if (a.status) active += 1; }
return [{ json: { ok: true, at: new Date().toISOString(), agents, needs_owner: agg.needs_owner || [], totals: { open, in_progress: inProg, active, paused, needs_owner: (agg.needs_owner || []).length }, sources: { task_rows: agg.task_rows || 0, registry_rows: reg.length } } }];
